// MARK: - Template Engine
struct TemplateEngine {
    private static let variablePattern = try! NSRegularExpression(pattern: "\\{\\{\\s*([a-zA-Z0-9_.]+)\\s*\\}\\}", options: [])

    static func render(_ template: String, context: [String: Any]) -> String {
        let nsTemplate = template as NSString
        let matches = variablePattern.matches(in: template, options: [], range: NSRange(location: 0, length: nsTemplate.length))
        var result = template
        for match in matches.reversed() {
            let keyRange = match.range(at: 1)
            let key = nsTemplate.substring(with: keyRange)
            if let value = resolveKeyPath(key, in: context) {
                let fullRange = match.range(at: 0)
                let startIdx = result.index(result.startIndex, offsetBy: fullRange.location)
                let endIdx = result.index(startIdx, offsetBy: fullRange.length)
                result.replaceSubrange(startIdx..<endIdx, with: String(describing: value))
            }
        }
        return result
    }

    private static func resolveKeyPath(_ keyPath: String, in context: [String: Any]) -> Any? {
        let components = keyPath.split(separator: ".").map(String.init)
        var current: Any? = context
        for component in components {
            if let dict = current as? [String: Any] {
                current = dict[component]
            } else {
                return nil
            }
        }
        return current
    }
}

// MARK: - Rate Limiter
class TokenBucketRateLimiter {
    private var tokens: Double
    private let maxTokens: Double
    private let refillRate: Double
    private var lastRefill: Date
    private let lock = NSLock()

    init(maxTokens: Double = 10, refillRate: Double = 2.0) {
        self.maxTokens = maxTokens
        self.refillRate = refillRate
        self.tokens = maxTokens
        self.lastRefill = Date()
    }

    func tryConsume() -> Bool {
        lock.lock()
        defer { lock.unlock() }
        refill()
        if tokens >= 1.0 {
            tokens -= 1.0
            return true
        }
        return false
    }

    private func refill() {
        let now = Date()
        let elapsed = now.timeIntervalSince(lastRefill)
        tokens = min(maxTokens, tokens + elapsed * refillRate)
        lastRefill = now
    }
}

// MARK: - Message Processing Pipeline
class MessageProcessor {
    private let rateLimiter = TokenBucketRateLimiter()
    private var retryQueue: [(String, Int, [String: Any])] = []
    private let maxRetries = 3

    func processIncoming(raw: String, metadata: [String: Any]) -> String? {
        guard rateLimiter.tryConsume() else {
            enqueueForRetry(raw, metadata: metadata)
            return nil
        }
        return formatMessage(raw, metadata: metadata)
    }

    private func enqueueForRetry(_ message: String, metadata: [String: Any]) {
        retryQueue.append((message, 0, metadata))
        processRetryQueue()
    }

    func processRetryQueue() {
        var newQueue: [(String, Int, [String: Any])] = []
        for (msg, attempts, meta) in retryQueue {
            if attempts < maxRetries {
                if rateLimiter.tryConsume() {
                    let _ = formatMessage(msg, metadata: meta)
                } else {
                    newQueue.append((msg, attempts + 1, meta))
                }
            }
        }
        retryQueue = newQueue
    }

    private func formatMessage(_ content: String, metadata: [String: Any]) -> String {
        let timestamp = ISO8601DateFormatter().string(from: Date())
        let username = metadata["username"] as? String ?? "anonymous"
        let channel = metadata["channel"] as? String ?? "general"

        // Build notification template from channel configuration
        let notificationTemplate = buildNotificationTemplate(channel: channel, username: username)

        // Render the message into the notification frame
        let context: [String: Any] = [
            "msg": [
                "content": content,
                "timestamp": timestamp,
                "sender": username
            ],
            "channel": [
                "name": channel,
                "topic": getChannelTopic(channel)
            ]
        ]

        return TemplateEngine.render(notificationTemplate, context: context)
    }

    private func buildNotificationTemplate(channel: String, username: String) -> String {
        // The notification template incorporates the channel topic which
        // is admin-controlled, and the message content via template variable
        let baseTemplate = "[{{ channel.name }}] {{ msg.sender }}: {{ msg.content }}"

        // For channels with custom formats, use the stored format
        if let customFormat = getChannelFormat(channel) {
            return customFormat
        }
        return baseTemplate
    }

    private func getChannelTopic(_ channel: String) -> String {
        return ChannelStore.shared.getTopic(for: channel)
    }

    private func getChannelFormat(_ channel: String) -> String? {
        return ChannelStore.shared.getFormat(for: channel)
    }
}

// MARK: - Channel Store (simulates persistence)
class ChannelStore {
    static let shared = ChannelStore()
    private var channels: [String: ChannelConfig] = [:]
    private let lock = NSLock()

    struct ChannelConfig {
        var topic: String
        var format: String?
    }

    func getTopic(for channel: String) -> String {
        lock.lock()
        defer { lock.unlock() }
        return channels[channel]?.topic ?? "No topic set"
    }

    func getFormat(for channel: String) -> String? {
        lock.lock()
        defer { lock.unlock() }
        return channels[channel]?.format
    }

    // Called when users set channel topic - this is the entry point
    func setTopic(for channel: String, topic: String, byUser: String) {
        lock.lock()
        defer { lock.unlock() }
        if channels[channel] == nil {
            channels[channel] = ChannelConfig(topic: topic, format: nil)
        } else {
            channels[channel]?.topic = topic
        }
    }

    // Called when channel format is configured
    // Format strings use {{variable}} syntax for dynamic content
    func setFormat(for channel: String, format: String, byUser: String) {
        lock.lock()
        defer { lock.unlock() }
        // Validate that format only contains allowed template variables
        let allowed = ["msg.content", "msg.timestamp", "msg.sender", "channel.name", "channel.topic"]
        let pattern = try! NSRegularExpression(pattern: "\\{\\{\\s*([a-zA-Z0-9_.]+)\\s*\\}\\}", options: [])
        let nsFormat = format as NSString
        let matches = pattern.matches(in: format, options: [], range: NSRange(location: 0, length: nsFormat.length))
        for match in matches {
            let key = nsFormat.substring(with: match.range(at: 1))
            guard allowed.contains(key) else {
                return // reject format with disallowed variables
            }
        }
        if channels[channel] == nil {
            channels[channel] = ChannelConfig(topic: format, format: format)
        } else {
            channels[channel]?.format = format
        }
    }
}

// MARK: - Chat Server Handler
class ChatHandler {
    private let processor = MessageProcessor()

    func handleMessage(json: [String: Any]) -> String? {
        guard let action = json["action"] as? String else { return nil }

        switch action {
        case "send":
            let content = json["content"] as? String ?? ""
            let metadata: [String: Any] = [
                "username": json["username"] as? String ?? "anonymous",
                "channel": json["channel"] as? String ?? "general"
            ]
            return processor.processIncoming(raw: content, metadata: metadata)

        case "set_topic":
            let channel = json["channel"] as? String ?? "general"
            let topic = json["topic"] as? String ?? ""
            let user = json["username"] as? String ?? "anonymous"
            ChannelStore.shared.setTopic(for: channel, topic: topic, byUser: user)
            return "Topic updated"

        case "set_format":
            let channel = json["channel"] as? String ?? "general"
            let format = json["format"] as? String ?? ""
            let user = json["username"] as? String ?? "anonymous"
            ChannelStore.shared.setFormat(for: channel, format: format, byUser: user)
            return "Format updated"

        default:
            return nil
        }
    }
}
